    action_defs = {
        "VIEW": "Xem dữ liệu",
        "CREATE": "Thêm mới",
        "EDIT": "Cập nhật",
        "DELETE": "Xóa",
        "CALCULATE": "Tính đánh giá lại ngoại tệ",
        "RUN": "Chạy và tạo chứng từ đánh giá lại ngoại tệ",
        "POST": "Ghi sổ bút toán đánh giá lại ngoại tệ",
        "UNPOST": "Bỏ ghi sổ bút toán đánh giá lại ngoại tệ",
    }
    actions = {}
    for code, name in action_defs.items():
        actions[code], _ = Action.objects.get_or_create(
            code=code,
            defaults={
                "id": uuid.uuid4(),
                "name": name,
                "risk_level": "HIGH" if code in ("RUN", "POST", "UNPOST", "DELETE") else "MEDIUM",
            },
        )

    created_perms = []
    for res_code in ("GL.REVALUATION", "GL.FX_REVALUATION"):
        resource, _ = Resource.objects.get_or_create(
            code=res_code,
            defaults={
                "id": uuid.uuid4(),
                "module_code": "GL",
                "name": "Đánh giá lại tài khoản ngoại tệ cuối kỳ",
                "status": "ACTIVE",
            },
        )
        for act_code, act_name in action_defs.items():
            perm, _ = Permission.objects.get_or_create(
                code=f"{res_code}.{act_code}",
                defaults={
                    "id": uuid.uuid4(),
                    "resource_id": resource.id,
                    "action_id": actions[act_code].id,
                    "description": f"{act_name} - Đánh giá lại tài khoản ngoại tệ GL",
                    "status": "ACTIVE",
                },
            )
            created_perms.append(perm)

    for role in Role.objects.all():
        for perm in created_perms:
            RolePermission.objects.get_or_create(
                role_id=role.id,
                permission_id=perm.id,
                defaults={"effect": "ALLOW"},
            )


